"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[3697],{6174(a){a.exports=JSON.parse('{"title":"UI \ub77c\uc774\ube0c\ub7ec\ub9ac, \uc368\uc57c \ud558\ub098\uc694 \ub9cc\ub4e4\uc5b4\uc57c \ud558\ub098\uc694?","date":"2024-08-22","coverUrl":null,"html":"<h2 data-notion-block-id=\\"84e4c96d-1755-437d-a118-99c23ed06de8\\" id=\\"84e4c96d-1755-437d-a118-99c23ed06de8\\">UI \ub77c\uc774\ube0c\ub7ec\ub9ac, \uc368\uc57c \ud558\ub098\uc694 \ub9cc\ub4e4\uc5b4\uc57c \ud558\ub098\uc694?</h2><a href=\\"https://component-odyssey.com/articles/10-what-is-a-library-should-you-build-your-own\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://component-odyssey.com/articles/10-what-is-a-library-should-you-build-your-own</a><p data-notion-block-id=\\"3c2c3f02-e372-460e-8a68-5907d2510bec\\"><b>\uc2ec\uc724\uc12d</b>: UI \ucef4\ud3ec\ub10c\ud2b8 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc758 \uc5ed\uc0ac\uc640 \uc7a5\ub2e8\uc810\uc744 \uc18c\uac1c\ud569\ub2c8\ub2e4. \ucd94\ucc9c\ud558\ub294 \ubc29\uc2dd\uc744 \ub2e8\uacc4\ubcc4\ub85c \uc124\uba85\ud558\uace0 \uc788\uc5b4 \ucef4\ud3ec\ub10c\ud2b8 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \uc120\ud0dd\ud558\ub294 \ubc29\uc2dd\uc744 \uc54c\uc544\ubcfc \uc218 \uc788\ub294 \uae00\uc785\ub2c8\ub2e4. \uad00\ub828 \uc0c1\ud0dc(State machine)\uc774\ub098 \uad6c\uc870(Headless Component pattern)\ub9cc \uc81c\uacf5\ud574\uc8fc\ub294 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub3c4 \uc874\uc7ac\ud558\uba70, CSS \uc2a4\ud0c0\uc77c\ub9cc \uc81c\uacf5\ud558\ub294 \ub77c\uc774\ube0c\ub7ec\ub9ac \ub610\ud55c \uc874\uc7ac\ud569\ub2c8\ub2e4. \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \uc0ac\uc6a9\ud574\uc11c \uc0ac\uc6a9\uc790\uc758 \uacbd\ud5d8\uc744 \uc77c\uad00\ub418\uac8c, \ube60\ub974\uac8c \uad6c\uc131\ud560 \uc218 \uc788\uc9c0\ub9cc, \ubca4\ub354 \ub77d\uc778\uacfc \uac19\uc774 \ubcc0\uacbd\ud558\uae30 \uc5b4\ub824\uc6b4 \ubd80\ubd84\ub3c4 \uc874\uc7ac\ud558\uae30 \ub54c\ubb38\uc5d0 \uc798 \uc870\ud569\ud574\uc11c \uc2dc\uc2a4\ud15c\uc744 \ub9cc\ub4e4\uc5b4\uc57c\uaca0\ub124\uc694. UI \ucef4\ud3ec\ub10c\ud2b8 \uc678\uc5d0\ub3c4 \ubaa8\ub4c8\ud654\ud55c \ub77c\uc774\ube0c\ub7ec\ub9ac\ub4e4\uc774 \ub9ce\uc774 \uc874\uc7ac\ud558\uae30 \ub54c\ubb38\uc5d0, <a href=\\"https://ones-to-watch.ethansup.net/news/post/43f27c92-8790-48e3-904c-82a7fab89e70#8d21a27c-c00e-4e7c-a4a9-4786e0ac9750\\">E18E</a>\uc5d0 \ub300\ud574 \uc0b4\ud3b4\ubcf4\uba74 \uc88b\uc2b5\ub2c8\ub2e4.</p><p data-notion-block-id=\\"9d0cfc71-dde9-49f3-823f-2bedbe658b7b\\"><b>\uae40\ub300\uad00</b>: UI \ucef4\ud3ec\ub10c\ud2b8 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub294 \uc0ac\uc6a9\uc790\uc5d0\uac8c \uc77c\uad00\ub41c \uacbd\ud5d8\uc744 \uc81c\uacf5\ud55c\ub2e4\ub294 \uc7a5\uc810\uc774 \uc788\uc9c0\ub9cc, \ud2b9\uc815 \ucef4\ud3ec\ub10c\ud2b8\uc5d0 \uc885\uc18d\ub420 \uacbd\uc6b0 \ub2e4\uc591\ud55c UI \ubcc0\uacbd\uc5d0 \uc5b4\ub824\uc6c0\uc774 \ub530\ub97c \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc790\uc2e0\uc774 \uc9c1\uba74\ud55c \ubb38\uc81c\uc5d0 \uac00\uc7a5 \uc801\ud569\ud55c UI \ucef4\ud3ec\ub10c\ud2b8 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \uc120\ud0dd\ud558\uae30 \uc704\ud574 <a href=\\"https://www.builder.io/blog/25-plus-ui-component-libraries\\">\ub2e4\uc591\ud55c \uae30\uc220\uc744 \ud0d0\uc0c9</a>\ud574\ubcf4\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"af64bad6-4310-4475-86c7-4a17a9e1e17b\\" id=\\"af64bad6-4310-4475-86c7-4a17a9e1e17b\\">\uc77c\ubc18\uc801\uc778 \uba54\ubaa8\ub9ac \ub204\uc218 \uc6d0\uc778</h2><a href=\\"https://www.trevorlasn.com/blog/common-causes-of-memory-leaks-in-javascript\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.trevorlasn.com/blog/common-causes-of-memory-leaks-in-javascript</a><p data-notion-block-id=\\"aa1699e4-4c76-43a8-980b-f83a770e15a0\\"><b>\uc2ec\uc724\uc12d</b>: V8\uc5d0\uc11c \uc124\uba85\ud558\ub294 \uba54\ubaa8\ub9ac\uc5d0 \ub300\ud55c \uc804\ubc18\uc801\uc778 \uc124\uba85\uacfc \uc77c\ubc18\uc801\uc73c\ub85c \uc0dd\uae30\ub294 \uba54\ubaa8\ub9ac \ub204\uc218 \uc6d0\uc778\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ub9ce\uc740 \uacbd\uc6b0\uc5d0 \ud074\ub85c\uc800\uc5d0 \uad00\ub828\ub418\uc5b4 \uc788\uc73c\ubbc0\ub85c \ubcc0\uc218 \uc0ac\uc6a9\ud558\ub294 \ubc29\uc2dd\uc5d0 \ub300\ud574\uc11c \uc8fc\uae30\uc801\uc778 \ubaa8\ub2c8\ud130\ub9c1\uc774 \ud544\uc694\ud574\ubcf4\uc785\ub2c8\ub2e4.  (\uc608\uc2dc- <a href=\\"https://ones-to-watch.ethansup.net/news/post/0269c0cd-b5f8-4f29-8457-f7976befb282#6e947f37-d04f-41c5-8898-9f0ab795f62d\\">NodeJS\uc5d0\uc11c setTimeout \uba54\ubaa8\ub9ac \ub204\uc218</a>, <a href=\\"https://ones-to-watch.ethansup.net/news/post/a5902c7d-ee33-4db6-aaea-ea4820a7562f#969cfc7b-5f89-42de-896d-eacff8b32799\\">React\uc5d0\uc11c\uc758 \uba54\ubaa8\ub9ac \ub204\uc218</a>)</p><p data-notion-block-id=\\"4fbce757-e363-4794-a9c0-732d6c1ac4e2\\"><b>\uae40\ub300\uad00</b>: \uc7a5\uae30\uac04 \uc2e4\ud589\ub418\ub294 \uc11c\ubc84 \uc560\ud50c\ub9ac\ucf00\uc774\uc158\uc5d0\uc11c \uba54\ubaa8\ub9ac \ub204\uc218\ub294 \uc131\ub2a5 \uc800\ud558\uc640 \uc2dc\uc2a4\ud15c \ubd88\uc548\uc815\uc758 \uc8fc\uc694 \uc6d0\uc778 \uc911 \ud558\ub098\ub85c \uc791\uc6a9\ud560 \uc218 \uc788\uc74c\uc744 \uc778\uc9c0\ud574\uc57c\ud569\ub2c8\ub2e4. \uc774\ub97c \ud574\uacb0\ud558\uae30 \uc704\ud574\uc11c\ub294 \ub2e8\uc21c\ud788 \ucf54\ub4dc\ub97c \uc791\uc131\ud558\ub294 \uac83\uc744 \ub118\uc5b4, \uae00\uc5d0 \uc788\ub294 \uba54\ubaa8\ub9ac \ub204\uc218 \ud328\ud134\uc744 \uc774\ud574\ud558\uace0 \uc8fc\uae30\uc801\uc73c\ub85c \uc774\ub97c \uac80\ud1a0\ud558\ub294 \uc2b5\uad00\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"537bdbf9-8b12-424b-b290-765d0c82e635\\" id=\\"537bdbf9-8b12-424b-b290-765d0c82e635\\">SPA\uc5d0\uc11c chunk \ud504\ub9ac\ub85c\ub529 \uc124\uc815\uc73c\ub85c \uc131\ub2a5 \ud5a5\uc0c1</h2><a href=\\"https://mmazzarolo.com/blog/2024-08-13-async-chunk-preloading-on-load/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://mmazzarolo.com/blog/2024-08-13-async-chunk-preloading-on-load/</a><p data-notion-block-id=\\"24164fa7-dfbd-4853-915c-a7c5de9dd396\\"><b>\uc2ec\uc724\uc12d</b>: <code>React.lazy</code>\ub97c \uc0ac\uc6a9\ud558\uba74 \ubc1c\uc0dd\ud558\ub294 waterfall \ub85c\ub529 \ubb38\uc81c\uc640 \uc774\ub97c \ud574\uacb0\ud558\uae30 \uc704\ud574 \ud504\ub9ac\ub85c\ub529 \uc2a4\ud06c\ub9bd\ud2b8\ub97c \uc0bd\uc785\ud558\ub294 \ubc29\uc2dd\uc744 webpack\uc5d0\uc11c \uc801\uc6a9\ud558\ub294 \ubc29\ubc95\uc744 \uc124\uba85\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. <code>@tanstack/query</code>\uc73c\ub85c \uc11c\ubc84 \ub370\uc774\ud130\ub97c \ud504\ub9ac\ub85c\ub529\ud558\ub294 \ubc29\uc2dd\ub3c4 \uc788\uc73c\ub2c8 \uc5ec\ub7ec\uac00\uc9c0\ub97c \uace0\ub824\ud574\uc57c\uaca0\ub124\uc694.</p><h2 data-notion-block-id=\\"cf94f5db-2856-4624-a051-51bab2c1da69\\" id=\\"cf94f5db-2856-4624-a051-51bab2c1da69\\">CSS \uc2a4\ud0c0\uc77c Cascading \ub2e8\uacc4\uc640 \uc6f9 \ucef4\ud3ec\ub10c\ud2b8 \ud65c\uc6a9\ubc95 \uc54c\uc544\ubcf4\uae30</h2><a href=\\"https://scottjehl.com/posts/html-web-components-shadow-dom/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://scottjehl.com/posts/html-web-components-shadow-dom/</a><p data-notion-block-id=\\"5f446c29-4411-4395-9677-aa45aadd8cca\\"><b>\uc2ec\uc724\uc12d</b>: Shadow DOM\uc744 \ud1b5\ud574 \uc2a4\ud0c0\uc77c \uc801\uc6a9 \ub2e8\uacc4\ub97c \ud65c\uc6a9\ud574\uc11c \uc0ac\uc6a9\uc790 \uc815\uc758 \uc2a4\ud0c0\uc77c\ub9c1\uacfc \ucef4\ud3ec\ub10c\ud2b8 \uae30\ubcf8 \uc2a4\ud0c0\uc77c\uc774 \ucda9\ub3cc\uc774 \uc548\ub098\ub3c4\ub85d \ub9cc\ub4dc\ub294 \ubc29\ubc95\uc5d0 \ub300\ud574 \uc81c\uc548\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uc6f9 \ucef4\ud3ec\ub10c\ud2b8\ub77c \ub9ce\uc740 \uacbd\uc6b0\uc5d0 \uc801\uc6a9\ub418\uc9c0 \uc54a\uc9c0\ub9cc <a href=\\"https://css-tricks.com/css-cascade-layers/#aa-where-do-layers-fit-in-the-cascade\\">\uc5f0\uad00 \uae00\uc758 Cascading \ub2e8\uacc4</a>\ub294 \ub098\uc911\uc744 \uc704\ud574 \uc54c\uc544\ub450\ub294 \uac83\uc740 \ub098\uc058\uc9c0 \uc54a\ub124\uc694.</p><h2 data-notion-block-id=\\"08be7f66-9813-4aa6-9a07-d6711dd603c2\\" id=\\"08be7f66-9813-4aa6-9a07-d6711dd603c2\\">\ud0c0\uc785\uc2a4\ud06c\ub9bd\ud2b8 \uac80\uc0ac \ubca4\uce58\ub9c8\ud06c \uacfc\uc815</h2><a href=\\"https://www.edgedb.com/blog/an-approach-to-optimizing-typescript-type-checking-performance#how-do-we-quantify-the-type-checker-s-workload\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.edgedb.com/blog/an-approach-to-optimizing-typescript-type-checking-performance#how-do-we-quantify-the-type-checker-s-workload</a><p data-notion-block-id=\\"951803f1-9bb5-424c-a707-c3916da6192f\\">\ud0c0\uc785\uc2a4\ud06c\ub9bd\ud2b8\uc5d0\uc11c \ud0c0\uc785 \uac80\uc0ac\uac00 \ub9ce\uc740 \ud30c\uc77c\uc744 \uac70\uce58\uac8c \ub418\uba74 \ub9ce\uc740 \uc2dc\uac04\uc774 \uac78\ub9b4 \ub54c\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \uadf8\ub7ec\uba74 CI/CD\ub098 IDE \uc218\uc815\uc5d0\uc11c \uc2dc\uac04\uc774 \ub9ce\uc774 \uac78\ub9b4 \uc218\ub3c4 \uc788\uae30 \ub54c\ubb38\uc5d0 \ud0c0\uc785 \uac80\uc0ac \ubca4\uce58\ub9c8\ud06c\ub97c \ud558\ub294 \uac83\uc740 \ub54c\uc5d0 \ub530\ub77c \uc911\uc694\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uadf8\uac83\uc774 \uc544\ub2c8\ub354\ub77c\ub3c4 \ud0c0\uc785 \uac80\uc0ac\ub97c \ube60\ub974\uac8c \ud558\ub294 \ud301\ub3c4 \uc81c\uacf5\ud558\uae30 \ub54c\ubb38\uc5d0 \ud55c \ubc88 \uac00\ubccd\uac8c \ubcf4\ub294 \uac83\ub3c4 \ub098\uc058\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"3f23e546-36d1-49a3-bd68-813178a94035\\" id=\\"3f23e546-36d1-49a3-bd68-813178a94035\\">\ud53c\uadf8\ub9c8\uac00 SVG\ub85c \ub0b4\ubcf4\ub0b4\uae30\ud558\ub294 \uacfc\uc815</h2><a href=\\"https://courses.nan.fyi/blog/svg/animating-figma-exports\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://courses.nan.fyi/blog/svg/animating-figma-exports</a><p data-notion-block-id=\\"1a78e54d-1b53-482c-906b-38443692ed0a\\">\ud53c\uadf8\ub9c8\uac00 \uc694\uc18c\ub97c SVG\ub85c \ub0b4\ubcf4\ub0b4\uae30 \ud560 \ub54c \uc5b4\ub5a4 \uacfc\uc815\uc744 \uac70\uce58\ub294\uc9c0 \uc124\uba85\ud558\uace0 SVG \uc694\uc18c\ub9c8\ub2e4 \uc560\ub2c8\uba54\uc774\uc158\uc744 \uc5b4\ub5bb\uac8c \ub123\uc5b4\uc57c \ud558\ub294\uc9c0 \uac00\uc774\ub4dc\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uc544\uc774\ucf58\uc5d0 \uac04\ub2e8\ud55c \uc560\ub2c8\uba54\uc774\uc158\uc744 \ub123\uc744 \ub54c \ub3c4\uc6c0\uc774 \ub420 \uac83 \uac19\ub124\uc694.</p><h2 data-notion-block-id=\\"e12fd33d-db6e-4beb-ac39-f6f059115c00\\" id=\\"e12fd33d-db6e-4beb-ac39-f6f059115c00\\">Node.js\uc5d0\uc11c corepack \uc0ac\ub77c\uc9c8 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.</h2><a href=\\"https://socket.dev/blog/node-js-takes-steps-towards-removing-corepack\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://socket.dev/blog/node-js-takes-steps-towards-removing-corepack</a><p data-notion-block-id=\\"6fcd5fa7-aa00-4a61-a9ae-07b05e40bf2f\\">Node.js\uc5d0\uc11c corepack\uc744 \uc0ad\uc81c\ud558\ub294 PR\uc5d0 \ub300\ud55c \ub17c\uc758\uac00 \ub2e4\uc2dc \uc9c4\ud589\ub418\uace0 \uc788\ub2e4\ub294 \uac04\ub2e8\ud55c \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"29340dca-1a16-4383-b751-d5ddae6a5c20\\" id=\\"29340dca-1a16-4383-b751-d5ddae6a5c20\\">React \uad00\ub828 \ud29c\ud1a0\ub9ac\uc5bc</h2><a href=\\"https://www.saybackend.com/blog/03-electron-nextjs-ssr\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.saybackend.com/blog/03-electron-nextjs-ssr</a><a href=\\"https://ui.dev/c/react/effects\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://ui.dev/c/react/effects</a><a href=\\"https://www.epicreact.dev/react-forms\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.epicreact.dev/react-forms</a><p data-notion-block-id=\\"3e872501-0f4c-441a-8ba0-98783202ac13\\">\uc21c\uc11c\ub300\ub85c Electron\uc5d0\uc11c Next.js app router\ub97c \uc0ac\uc6a9\ud558\ub294 \uacfc\uc815\uc744 \ub2f4\uc740 \uae00, React\uc5d0\uc11c Side Effect\ub97c \ub2e4\ub8e8\ub294 \ubc29\uc2dd, React \uc2e0 \uae30\ub2a5\uc778 form \uad00\ub828 \uae30\ub2a5\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><p data-notion-block-id=\\"dea391d4-8ea3-45fa-8fb3-018b4c6a88e2\\"></p>"}')}}]);